MODULE='from __future__ import annotations\nfrom datetime import datetime,timezone\nfrom pathlib import Path\nimport time,os,uuid\n\nfrom .oph_006_durable_cross_process_observation_queue import (\n    claim_next_request,\n    complete_request,\n    fail_request,\n    queue_counts,\n)\nfrom .oph_007_physical_single_postgresql_writer_runtime import (\n    build_existing_canonical_router,\n)\nfrom .oph_011_persistence_provenance_ledger import append_provenance\n\nOPH_014_BUILD_ID="OPH-014"\nOPH_014_REVISION="OPH_014_CANONICAL_WRITER_FAILURE_RECOVERY_RUNTIME_V1"\n\nTRANSIENT_NAMES={\n    "PostgreSQLPersistenceRoutingFailure",\n    "OperationalError",\n    "InterfaceError",\n}\n\ndef _is_transient(exc):\n    name=type(exc).__name__\n    text=str(exc).lower()\n    return (\n        name in TRANSIENT_NAMES\n        or "expected_terminal_chain_hash_mismatch" in text\n        or "connection" in text and "postgres" in text\n    )\n\ndef run_recovering_single_writer_forever(\n    root=None,\n    progress=None,\n    idle_sleep_seconds=0.002,\n    retry_limit=5,\n):\n    root=Path(root or Path.cwd()).resolve()\n    worker_id=f"oph014:{os.getpid()}:{uuid.uuid4().hex[:8]}"\n    router=build_existing_canonical_router(root)\n\n    if progress:\n        progress(\n            f"[SINGLE WRITER] worker={worker_id} "\n            f"queue={queue_counts(root)} recovery=ENABLED"\n        )\n\n    while True:\n        try:\n            item=claim_next_request(worker_id,root)\n            if item is None:\n                time.sleep(float(idle_sleep_seconds))\n                continue\n\n            request_id,writer_id,priority,observations=item\n            attempt=0\n\n            while True:\n                attempt+=1\n                started=time.perf_counter()\n\n                append_provenance(\n                    "WRITER_ATTEMPT",\n                    root,\n                    request_id=request_id,\n                    producer=writer_id,\n                    priority=priority,\n                    observation_count=len(observations),\n                    attempt=attempt,\n                )\n\n                try:\n                    result=tuple(\n                        router.route_batch(\n                            tuple(observations),\n                            datetime.now(timezone.utc),\n                        )\n                    )\n\n                    complete_request(\n                        request_id,\n                        result,\n                        root,\n                    )\n\n                    append_provenance(\n                        "WRITER_SUCCESS",\n                        root,\n                        request_id=request_id,\n                        producer=writer_id,\n                        priority=priority,\n                        observation_count=len(observations),\n                        attempt=attempt,\n                        elapsed_ms=round(\n                            (time.perf_counter()-started)*1000,\n                            2,\n                        ),\n                    )\n\n                    if progress:\n                        progress(\n                            f"[SINGLE WRITER] request={request_id[:10]} "\n                            f"producer={writer_id} priority={priority} "\n                            f"observations={len(observations)} "\n                            f"attempt={attempt} "\n                            f"elapsed_ms={(time.perf_counter()-started)*1000:.2f}"\n                        )\n\n                    break\n\n                except Exception as exc:\n                    transient=_is_transient(exc)\n\n                    append_provenance(\n                        "WRITER_FAILURE",\n                        root,\n                        request_id=request_id,\n                        producer=writer_id,\n                        priority=priority,\n                        observation_count=len(observations),\n                        attempt=attempt,\n                        exception_type=type(exc).__name__,\n                        exception_message=str(exc),\n                        transient=transient,\n                    )\n\n                    if transient and attempt<int(retry_limit):\n                        delay=min(\n                            0.50,\n                            0.01*(2**(attempt-1)),\n                        )\n\n                        if progress:\n                            progress(\n                                f"[SINGLE WRITER RETRY] request={request_id[:10]} "\n                                f"producer={writer_id} "\n                                f"type={type(exc).__name__} "\n                                f"attempt={attempt}/{retry_limit} "\n                                f"delay={delay:.3f}s"\n                            )\n\n                        time.sleep(delay)\n\n                        # Refresh router after a failed physical append.\n                        router=build_existing_canonical_router(root)\n                        continue\n\n                    fail_request(\n                        request_id,\n                        exc,\n                        root,\n                    )\n\n                    if progress:\n                        progress(\n                            f"[SINGLE WRITER] FAILED request={request_id[:10]} "\n                            f"producer={writer_id} "\n                            f"type={type(exc).__name__} "\n                            f"attempts={attempt}"\n                        )\n\n                    break\n\n        except KeyboardInterrupt:\n            return 0\n\ndef verify_oph_014_canonical_writer_failure_recovery_runtime():\n    class E(Exception): pass\n    e=E("x")\n    return (\n        _is_transient(type("PostgreSQLPersistenceRoutingFailure",(Exception,),{})())\n        and not _is_transient(e)\n    )\n';TESTSRC='import unittest\nfrom qseries_v2.oracle_production_hardening.oph_014_canonical_writer_failure_recovery_runtime import verify_oph_014_canonical_writer_failure_recovery_runtime\nclass T(unittest.TestCase):\n    def test_verifier(self): self.assertTrue(verify_oph_014_canonical_writer_failure_recovery_runtime())\nif __name__=="__main__":\n    print("="*80);print(" OPH-014 CERTIFICATION TEST");print(" CANONICAL WRITER FAILURE RECOVERY RUNTIME");print("="*80)\n    r=unittest.TextTestRunner(verbosity=2).run(unittest.defaultTestLoader.loadTestsFromTestCase(T))\n    if not r.wasSuccessful():raise SystemExit(1)\n    print("[PASS] OPH-014 certified");print("[DONE] OPH-014 CERTIFIED")\n'

def write_exact(p,s):
    p.parent.mkdir(parents=True,exist_ok=True);t=p.with_suffix(p.suffix+".tmp");t.write_text(s,encoding="utf-8",newline="\n");os.replace(t,p)

